Previous dependency contracts: {"@modelcontextprotocol/server-filesystem::search_files": {"server": "@modelcontextprotocol/server-filesystem", "name": "search_files", "description": "Recursively search for files and directories matching a pattern. The patterns should be glob-style patterns that match paths relative to the working directory. Use pattern like '*.ext' to match files in current directory, and '**/*.ext' to match files in all subdirectories. Returns full paths to all matching items. Great for finding files when you don't know their exact location. Only searches within allowed directories.", "inputSchema": {"$schema": "http://json-schema.org/draft-07/schema#", "additionalProperties": false, "properties": {"excludePatterns": {"default": [], "items": {"type": "string"}, "type": "array"}, "path": {"type": "string"}, "pattern": {"type": "string"}}, "required": ["path", "pattern"], "type": "object"}}, "@modelcontextprotocol/server-filesystem::read_text_file": {"server": "@modelcontextprotocol/server-filesystem", "name": "read_text_file", "description": "Read the complete contents of a file from the file system as text. Handles various text encodings and provides detailed error messages if the file cannot be read. Use this tool when you need to examine the contents of a single file. Use the 'head' parameter to read only the first N lines of a file, or the 'tail' parameter to read only the last N lines of a file. Operates on the file as text regardless of extension. Only works within allowed directories.", "inputSchema": {"$schema": "http://json-schema.org/draft-07/schema#", "additionalProperties": false, "properties": {"head": {"description": "If provided, returns only the first N lines of the file", "type": "number"}, "path": {"type": "string"}, "tail": {"description": "If provided, returns only the last N lines of the file", "type": "number"}}, "required": ["path"], "type": "object"}}}
